fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let ax: i32 = cx + tab[(t / 2) & 31] * 100 / 127;
    let ay: i32 = cy + tab[(t / 2 + 8) & 31] * 80 / 127;
    let bx: i32 = cx + tab[(t / 3 + 16) & 31] * 110 / 127;
    let by: i32 = cy + tab[(t / 3 + 24) & 31] * 90 / 127;
    let gx: i32 = cx + tab[(t / 4 + 5) & 31] * 60 / 127;
    let gy: i32 = cy + tab[(t / 4 + 21) & 31] * 120 / 127;
    let cell: i32 = 8;
    let mut y: i32 = 0;
    while y < h {
        let mut x: i32 = 0;
        while x < w {
            let mx: i32 = x + cell / 2;
            let my: i32 = y + cell / 2;
            let d1: i32 = (mx - ax) * (mx - ax) + (my - ay) * (my - ay);
            let d2: i32 = (mx - bx) * (mx - bx) + (my - by) * (my - by);
            let d3: i32 = (mx - gx) * (mx - gx) + (my - gy) * (my - gy);
            let f: i32 = 260000 / (d1 + 40) + 260000 / (d2 + 40) + 170000 / (d3 + 40);
            let mut c: i32 = 0x061206;
            if f > 100 { c = 0x1f8f4a; }
            if f > 150 { c = 0x66e07a; }
            if f > 240 { c = 0xdfffd0; }
            host::display::fill_rect(x, y, cell, cell, c);
            x = x + cell;
        }
        y = y + cell;
    }
    host::display::present();
}
